"  const applyContractedTransportUsageOptionPricing = (
    service = {},
    optionKeysStr = "",
    availableServices = [],
    fallbackRate = 0,
    fallbackCurrency = "INR",
  ) => {
    const keys = String(optionKeysStr || "").split(",").filter(Boolean);
    if (keys.length === 0) {
      keys.push("one-way-airport-transfer");
    }

    const availableOptions = getTransportUsageOptionsForService(availableServices, service);

    let totalRate = 0;
    const labels = [];
    const usageTypes = [];
    let sourceServiceId = service.serviceId;
    let resolvedCurrency = fallbackCurrency || service.currency || "INR";

    keys.forEach((key) => {
      const normalizedKey = normalizeTransportUsageOptionKey(key);
      const option = availableOptions.find((item) => item.value === normalizedKey);
      const optionMeta = getTransportUsageOptionMeta(normalizedKey);

      const price = option?.price ?? getTransportUsageOptionDisplayPrice(service, normalizedKey);
      totalRate += roundCurrencyAmount(price);
      labels.push(option?.label || optionMeta.label);
      usageTypes.push(option?.usageType || optionMeta.usageType);
      if (option?.sourceServiceId) {
        sourceServiceId = option.sourceServiceId;
      }
      if (option?.currency) {
        resolvedCurrency = option.currency;
      }
    });

    return {
      ...service,
      serviceId: sourceServiceId,
      transportUsageOptionKey: keys.join(","),
      transportUsageLabel: labels.join(", "),
      usageType: usageTypes.includes("full-day") ? "full-day" : (usageTypes.includes("half-day") ? "half-day" : "point-to-point"),
      rate: Math.max(0, totalRate),
      quoteBaseRate: 0,
      currency: normalizeCurrencyCode(resolvedCurrency),
      useStoredPricing: false,
    };
  };"

