    service = {},
    optionKey = "",
    availableServices = [],
    fallbackRate = 0,
    fallbackCurrency = "INR",
  ) => {
    const normalizedOptionKey = normalizeTransportUsageOptionKey(optionKey);
    const option = getTransportUsageOptionsForService(availableServices, service)
      .find((item) => item.value === normalizedOptionKey);
    const optionMeta = getTransportUsageOptionMeta(normalizedOptionKey);
    const resolvedRate = roundCurrencyAmount(option?.price ?? fallbackRate ?? service.rate ?? 0);
    const resolvedCurrency = normalizeCurrencyCode(option?.currency || fallbackCurrency || service.currency || "INR");
    return {
      ...service,
      serviceId: option?.sourceServiceId || service.serviceId,
      transportUsageOptionKey: normalizedOptionKey,
      transportUsageLabel: option?.label || optionMeta.label,
      usageType: option?.usageType || optionMeta.usageType || normalizeTransportUsageValue(service.usageType),
      rate: Math.max(0, resolvedRate),
      quoteBaseRate: 0,
      currency: resolvedCurrency,
      useStoredPricing: false,
    };
  };"
